<template><section class="mx-auto max-w-2xl space-y-5"><h1 class="text-2xl font-bold text-white">{{ $t('procPages.disputeTitle') }}</h1><form class="pc-card space-y-4" @submit.prevent="submit"><select v-model="form.order_id" required class="input-field"><option value="">{{ $t('procPages.selectOrder') }}</option><option v-for="order in orders" :key="order.id" :value="order.id">{{ order.id.slice(0, 8) }} · {{ order.status }}</option></select><input v-model.trim="form.reason_code" required class="input-field" :placeholder="$t('procPages.reasonPh')" /><textarea v-model.trim="form.description" required rows="5" class="input-field" :placeholder="$t('procPages.descPh')" /><p v-if="error" class="text-sm text-red-300">{{ error }}</p><button class="btn-primary">{{ $t('procPages.openDispute') }}</button></form></section></template>
<script setup lang="ts">
definePageMeta({ layout: 'procurement', middleware: ['auth'], alias: ['/buyer/disputes/new'] }); const route = useRoute(); const api = useCommerce(); const orders = ref<any[]>([]); const error = ref(''); const form = reactive({ order_id: String(route.query.order_id || ''), reason_code: '', description: '' })
async function submit() { try { await api.createDispute(form.order_id, { reason_code: form.reason_code, description: form.description }); await navigateTo('/market/buyer/disputes') } catch (e: any) { error.value = e?.data?.detail || e?.message } }
onMounted(async () => { try { orders.value = (await api.listOrders()).items } catch (e: any) { error.value = e?.data?.detail || e?.message } })
</script>
